namespace TrakHound.Services.Tables
{
    /// <summary>
    /// A SQL command generated by a Dialect, with the Parameters it references
    /// </summary>
    public class TrakHoundSqlStatement
    {
        /// <summary>
        /// The SQL text
        /// </summary>
        public string Text { get; }

        /// <summary>
        /// The Parameters referenced by the SQL text (null if none)
        /// </summary>
        public TrakHoundTableParameterCollection Parameters { get; }


        /// <summary>
        /// Creates a Statement with the specified SQL text and Parameters
        /// </summary>
        public TrakHoundSqlStatement(string text, TrakHoundTableParameterCollection parameters = null)
        {
            Text = text;
            Parameters = parameters;
        }
    }
}
